    signal.SIGILL: "SIGILL - Illegal instruction signal",
    signal.SIGFPE: "SIGFPE - Floating point error signal",
    signal.SIGSEGV: "SIGSEGV - Segmentation violation signal",
    signal.SIGTERM: "SIGTERM - Termination request signal",
    signal.SIGABRT: "SIGABRT - Abort (abnormal termination) signal",
}


def format_signal_summary(returncode: int):
    # A process killed by a signal is reported with a negative return code equal
    # to the negated signal number (subprocess convention).
    signum = -returncode if returncode < 0 else returncode
    summary = SIGNAL_SUMMARIES.get(signum)
    if summary is not None:
        return summary
    try:
        name = signal.Signals(signum).name
    except (ValueError, AttributeError):
        return f"process crashed with return code {returncode}"
    description = None
    try:
        description = signal.strsignal(signum)
    except (ValueError, AttributeError):
        description = None
    if description:
        return f"{name} - {description}"
    return f"{name} - crash signal"


